"""Fourteenth-century institutions, courts and regional context."""
import pathlib,json,urllib.parse
ROOT=pathlib.Path(__file__).resolve().parents[1];OUT=ROOT/'public/data';TAG='support-1300-0.23'
read=lambda f:json.loads((OUT/f).read_text(encoding='utf8'))
save=lambda f,d:(OUT/f).write_text(json.dumps(d,ensure_ascii=False,separators=(',',':'))+'\n',encoding='utf8',newline='\n')
wiki=lambda t:'https://en.wikipedia.org/wiki/'+urllib.parse.quote(t.replace(' ','_'))
def main():
 forms=read('governance.json');forms['records']=[v for v in forms['records'] if v.get('acquisition')!=TAG]
 def form(keys,a,b,tags,ref):forms['records'].append(dict(keys=keys.split('|'),start=a,end=b,tags=tags.split('|'),source=wiki(ref),sourceLabel='Forma institucional fechada · siglo XIV',priority=15,note='Institución histórica, no evaluación democrática ni ideología deducida del color.',acquisition=TAG))
 for keys,tags,ref in [
  ('FRA|CASTILE|ARAGON|PRT|ENGLAND|SCOTLAND|NAVARRE-KINGDOM|NORWAY-KINGDOM|DNK|SWE|BOHEMIA|HUNGARY-KINGDOM','monarchy|kingdom','Late Middle Ages'),('POLAND-MEDIEVAL|POLAND-KINGDOM','monarchy|kingdom','Kingdom of Poland'),('BYZANTINE|TREBIZOND','monarchy|empire','Byzantine Empire'),('MUSCOVY|LITHUANIA-DUCHY','monarchy|principality','Grand prince'),('HIST-Q12548','elective-monarchy|empire|feudal','Holy Roman Empire'),('SAXONY-ELECTORATE|ELECTORATE-BRANDENBURG','monarchy|electorate|feudal','Prince-elector'),('HESSE-UNITED','monarchy|principality|feudal','Landgraviate of Hesse'),('BURGUNDY-DUCHY|BAVARIA-DUCHY','monarchy|duchy|feudal','Duchy'),('SAVOY-COUNTY|URGELL-COUNTY','monarchy|feudal','Count'),('PAPAL-STATES','elective-monarchy|theocracy','Avignon Papacy'),('FLORENCE-REPUBLIC|HIST-Q4948|HIST-Q174306|HIST-Q208169','republic|oligarchy|city-state','Maritime republics'),('CHE','confederal','Old Swiss Confederacy'),('MARINID|MAMLUKS|GRANADA-EMIRATE','monarchy|sultanate','Sultanate'),('ILKHANATE|GOLDEN-HORDE','monarchy|khanate','Division of the Mongol Empire'),('JPN','monarchy|feudal','Kamakura shogunate'),('ETH|HIST-Q184536','monarchy|empire','Medieval Africa')]:form(keys,1300,1399,tags,ref)
 for keys,a,b,tags,ref in [
  ('YUAN',1300,1368,'monarchy|empire','Yuan dynasty'),('NORTHERN-YUAN',1368,1399,'monarchy|khanate','Northern Yuan'),('MING',1368,1399,'monarchy|empire','Ming dynasty'),('GORYEO',1300,1392,'monarchy|kingdom','Goryeo'),('JOS',1392,1399,'monarchy|kingdom','Joseon'),('DELHI-KHALJI',1300,1320,'monarchy|sultanate','Khalji dynasty'),('DELHI-TUGHLAQ',1320,1399,'monarchy|sultanate','Tughlaq dynasty'),('TIMURID',1370,1399,'monarchy|empire','Timurid Empire'),('SERBIA-KINGDOM',1300,1345,'monarchy|kingdom','Kingdom of Serbia (medieval)'),('SERBIA-EMPIRE',1346,1371,'monarchy|empire','Serbian Empire'),('BOSNIA-BANATE',1300,1376,'monarchy|principality','Banate of Bosnia'),('BOSNIA-KINGDOM',1377,1399,'monarchy|kingdom','Kingdom of Bosnia'),('CILICIA-KINGDOM',1300,1375,'monarchy|kingdom','Armenian Kingdom of Cilicia'),('OTT',1300,1399,'monarchy|principality','Ottoman dynasty'),('JPN',1300,1333,'regency','Shikken'),('TENOCHTITLAN',1325,1399,'monarchy|city-state','Tenochtitlan'),('CUSCO-KINGDOM',1300,1399,'monarchy|kingdom','Kingdom of Cusco'),('NORWAY-KINGDOM|DNK|SWE',1397,1399,'dynastic-union','Kalmar Union')]:form(keys,a,b,tags,ref)
 save('governance.json',forms)
 cs=read('identities.json')['countries'];places=read('historical-places.json');places['records']=[v for v in places['records'] if v.get('acquisition')!=TAG]
 def city(k,n,xy,a=1300,b=1399,grouped=False):
  v=dict(id='seat023-'+k+'-'+str(a)+'-'+urllib.parse.quote(n,safe=''),keys=[k],name=n,coordinates=xy,start=a,end=b,capital=True,role='Sede histórica · contorno pendiente' if isinstance(grouped,str) else 'Sede soberana · Estado agrupado' if grouped else 'Corte o capital histórica',source='https://www.wikidata.org/wiki/'+cs[k]['qid'],note='Sede de referencia, no perímetro urbano ni frontera de control; no acredita residencia continua durante guerras,regencias o itinerancias.',acquisition=TAG)
  if grouped:
   v.update(aggregateKey=grouped if isinstance(grouped,str) else 'HIST-Q12548',entityName=cs[k]['name'],note='La fuente agrupa el Estado dentro del contorno imperial. La sede abre su ficha sin inventar límites individuales ni atribuir al emperador toda la soberanía local.' if grouped is True else 'La fuente no ofrece un contorno propio de esta entidad en estos años. La sede permite consultar sus autoridades documentadas, sin atribuirle la superficie del agregado ni presuponer su integración administrativa en él.')
   v['id']+='-fallback-'+v['aggregateKey']
  places['records'].append(v)
 for k,n,xy in [('HESSE-UNITED','Kassel',[9.4797,51.3127]),('SAXONY-ELECTORATE','Wittenberg',[12.6484,51.8671]),('ELECTORATE-BRANDENBURG','Brandenburg an der Havel',[12.556,52.412])]:city(k,n,xy,grouped=True)
 for k,n,xy,a,b in [
  ('FRA','París',[2.3522,48.8566],1300,1399),('CASTILE','Valladolid · corte itinerante',[-4.7286,41.6523],1300,1399),('ARAGON','Zaragoza · instituciones',[-.8891,41.6488],1300,1399),('PRT','Lisboa',[-9.1393,38.7223],1300,1399),('ENGLAND','Londres',[-.1278,51.5074],1300,1399),('NAVARRE-KINGDOM','Pamplona',[-1.6458,42.8125],1300,1399),('GRANADA-EMIRATE','Granada',[-3.5986,37.1773],1300,1399),('BURGUNDY-DUCHY','Dijon',[5.0415,47.322],1300,1399),('POLAND-MEDIEVAL','Cracovia',[19.9445,50.0647],1300,1384),('POLAND-KINGDOM','Cracovia',[19.9445,50.0647],1385,1399),('LITHUANIA-DUCHY','Vilna',[25.2797,54.6872],1323,1399),
  ('MUSCOVY','Moscú',[37.6173,55.7558],1300,1399),('BYZANTINE','Constantinopla',[28.9784,41.0082],1300,1399),('TREBIZOND','Trebisonda',[39.7168,41.0027],1300,1399),('OTT','Bursa',[29.061,40.1885],1326,1368),('OTT','Edirne',[26.5557,41.6771],1369,1399),('MAMLUKS','El Cairo',[31.2357,30.0444],1300,1399),('ILKHANATE','Tabriz · corte ilkaní',[46.2919,38.0962],1300,1335),('TIMURID','Samarcanda',[66.9597,39.627],1370,1399),('YUAN','Dadu',[116.4074,39.9042],1300,1368),('MING','Nankín',[118.7969,32.0603],1368,1399),('GORYEO','Gaegyeong',[126.554,37.97],1300,1392),('JOS','Hanyang',[126.978,37.5665],1394,1398),('JOS','Gaegyeong',[126.554,37.97],1399,1399),('JPN','Kioto · corte imperial',[135.7681,35.0116],1300,1399),('JPN','Kamakura · gobierno militar',[139.5503,35.3192],1300,1333),('PAPAL-STATES','Aviñón · corte pontificia',[4.8055,43.9493],1309,1376),('PAPAL-STATES','Roma',[12.4964,41.9028],1377,1399),('TENOCHTITLAN','México-Tenochtitlan',[-99.1332,19.4326],1325,1399),('CUSCO-KINGDOM','Cusco',[-71.9675,-13.5319],1300,1399)]:city(k,n,xy,a,b)
 city('MING','Nankín',[118.7969,32.0603],1368,1374,grouped='YUAN')
 city('GORYEO','Gaegyeong',[126.554,37.97],1300,1362,grouped='YUAN')
 save('historical-places.json',places)
 context=read('historical-context.json');history=read('country-history.json');points=read('conflict-points.geojson')
 for obj,field in [(context,'events'),(history,'records')]:obj[field]=[v for v in obj[field] if not v['id'].startswith('review023-')]
 points['features']=[v for v in points['features'] if not v['id'].startswith('review023-')]
 rows=[
  ('hundred','conflict','FRA|ENGLAND',1337,1399,'Guerra de los Cien Años · inicio y primera fase','Pretensiones dinásticas y campañas distintas; el título francés reclamado porEduardoIII no implica control uniforme deFrancia. La serie termina en1399 por cobertura, no por el final del conflicto.','Hundred Years War',[1,47]),
  ('scotland','conflict','SCOTLAND|ENGLAND',1300,1357,'Guerras de independencia de Escocia','Guardianes,soberanos y pretendientes rivales tienen ventanas propias. El exilio deJuanBalliol no se presenta como gobierno efectivo continuo deEscocia.','Wars of Scottish Independence',[-3.8,56]),
  ('castile','conflict','CASTILE|FRA|ENGLAND',1366,1369,'Guerra civil castellana','PedroI yEnriqueII tienen pretensiones y cambios efectivos de gobierno; los dos reinados deEnrique se distinguen. La victoria de1369 no se anticipa a todo el período.','Castilian Civil War',[-4.2,40]),
  ('portugal','conflict','PRT|CASTILE',1383,1385,'Crisis portuguesa de1383–1385','Vacancia sucesoria,regencia y proclamación deJuanI son fases distintas. No se prolonga automáticamente el gobierno deFernandoI después de1383.','1383–1385 Portuguese interregnum',[-8,39]),
  ('byzantine','conflict','BYZANTINE|OTT|SERBIA-EMPIRE',1341,1354,'Guerra civil bizantina','JuanV yJuanVI representan poderes y coimperios distintos. Las restauraciones posteriores deJuanV y la usurpación deJuanVII de1390 se registran por separado, sin confundirTesalónica conConstantinopla.','Byzantine civil war of 1341–1347',[26,40]),
  ('yuan','transition','YUAN|NORTHERN-YUAN|MING',1351,1399,'Transición Yuan–Ming y poderes norteños','La toma deDadu de1368 no significa extinción instantánea de la corteYuan ni soberaníaMing retrospectiva. Yuan delNorte conserva ámbito y cronología propios.','Ming dynasty',None),
  ('goryeo','transition','GORYEO|JOS|YUAN|MING',1388,1399,'Goryeo y fundación de Joseon','El cambio de1392 distingue dinastías,autoridades y relaciones exteriores. La alternancia anterior deChungsuk/Chunghye y el título deShen no se convierten en un mandato continuo único.','Joseon',None),
  ('japan','conflict','JPN',1331,1392,'Kamakura,Kenmu y cortes japonesas rivales','Caída deKamakura en1333,RestauraciónKenmu y establecimientoAshikaga son hitos distintos. Cortes delNorte ySur coexisten; emperador,shogun yshikken tienen funciones diferentes. No se inventan fronteras de facción.','Nanboku-chō period',[135.7681,35.0116]),
  ('ilkhanate','transition','ILKHANATE|TIMURID|GOLDEN-HORDE|YUAN',1335,1399,'Fragmentación ilkaní y poderes sucesores','La muerte deAbuSaid de1335 abre regímenes rivales. Los poderes chobánidas,yalayeríes,muzaffaríes y otros requieren series regionales propias. Un título mongol no acredita administración de todo el antiguo imperio.','Ilkhanate',None),
  ('horde','conflict','GOLDEN-HORDE|TIMURID|MUSCOVY',1359,1399,'Horda de Oro · crisis y rivalidades','GranTurbulencia,ascenso deTokhtamysh y campañas deTimur tienen cronologías distintas; no se rellena el intervalo entre khanes por interpolación.','Great Troubles (Golden Horde)',[45,48]),
  ('delhi','transition','DELHI-KHALJI|DELHI-TUGHLAQ|TIMURID',1320,1399,'Delhi · Khalji,Tughlaq y campañas deTimur','La sustitución de dinastía de1320 y el saqueo deDelhi de1398 no son una sucesión administrativa uniforme. La presencia militar no acredita una anexión permanente de todo el sultanato.','Tughlaq dynasty',None),
  ('serbia','transition','SERBIA-KINGDOM|SERBIA-EMPIRE|BOSNIA-BANATE|BOSNIA-KINGDOM',1331,1399,'Serbia y Bosnia · títulos y fragmentación','Dušan rey desde1331 y emperador desde1346; Tvrtko pasa de ban a rey en1377. Los contornos posteriores a1371 no prueban un gobierno imperial serbio uniforme.','Serbian Empire',None),
  ('mali','transition','HIST-Q184536',1312,1337,'Mali · Mansa Musa y redes transaharianas','Cronología aproximada del reinado y peregrinación deMusa en los años1320. La representación delAtlas catalán de1375 es posterior al gobernante; no se presenta como fotografía contemporánea ni una frontera precisa de su administración.','Mansa Musa',None),
  ('avignon','transition','PAPAL-STATES|FRA|HIST-Q12548',1309,1399,'Aviñón y Cisma de Occidente','Sede pontificia,cargos y obediencias son dimensiones distintas. El retorno aRoma y el cisma desde1378 no se convierten en un papa único de control uniforme; las series de antipapas y gobiernos locales siguen parciales.','Avignon Papacy',None),
  ('plague','transition','FRA|ENGLAND|CASTILE|ARAGON|PRT|HIST-Q12548|BYZANTINE',1346,1353,'Peste negra · crisis social y demográfica','La cronología de propagación difiere entre regiones. Este contexto no es una capa epidemiológica ni cuantifica poblaciones locales sin datos de observación.','Black Death',None),
  ('golden-bull','transition','HIST-Q12548|SAXONY-ELECTORATE|ELECTORATE-BRANDENBURG',1356,1356,'Bula de Oro y dignidades electorales','La regulación electoral no unifica soberanías territoriales ni convierte al emperador en gobernante nacional de todos los miembros. Las sedes abren fichas independientes cuando están documentadas.','Golden Bull of 1356',None)]
 for id,kind,keys,a,b,title,text,ref,xy in rows:
  e=dict(id='review023-'+id,type=kind,countries=keys.split('|'),title=title,start=f'{a}-01-01',end=f'{b+1}-01-01',text=text,source=wiki(ref),sourceLabel='Referencia documental · siglo XIV',precision=9,startIsCoverageBoundary=True,endIsCoverageBoundary=True,note='Síntesis documental parcial, no reconstrucción diaria de control.')
  if id=='yuan':e['source']='https://www.metmuseum.org/essays/ming-dynasty-1368-1644'
  if id=='mali':e['source']='https://www.britishmuseum.org/exhibitions/asante-ewer/asante-ewer-large-print-guide'
  context['events'].append(e);history['records'].append(dict(id=e['id'],keys=e['countries'],section='history' if kind=='conflict' else 'institutions',**{k:v for k,v in e.items() if k not in ['id','countries','type']}))
  if xy:points['features'].append(dict(type='Feature',id=e['id'],geometry=dict(type='Point',coordinates=xy),properties=dict(name=title,countries=e['countries'],kind='regional-conflict',start=e['start'],end=f'{b}-12-31',precision=9,source=e['source'],sourceLabel=e['sourceLabel'],note=text+' Punto regional, no frente ni superficie ocupada.')))
 context['startYear']=1300;history['coverageStart']=1300;save('historical-context.json',context);save('country-history.json',history);save('conflict-points.geojson',points)
 print('New forms',sum(v.get('acquisition')==TAG for v in forms['records']),'new places',sum(v.get('acquisition')==TAG for v in places['records']),'new context',len(rows),'points',sum(v['id'].startswith('review023-') for v in points['features']))
if __name__=='__main__':main()
